INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4290244, 619450, 47316, '<td valign="top">Very handsome photos. Nice tones. What bugs me is that stick poking out of the side of your head. Something to watch out for. :)</td>', 'Very handsome photos. Nice tones. What bugs me is that stick poking out of the side of your head. Something to watch out for. :)', '2007-12-05 03:45:58.000000', NULL, 1),
(4290247, 618162, 53572, '<td valign="top">happy birthday, judy!</td>', 'happy birthday, judy!', '2007-12-05 03:48:06.000000', NULL, 1),
(4290249, 618341, 47316, '<td valign="top">This is a very pretty shot of you! Well done. I love your hair. I just have the feeling like... I wish either your head was up a bit or your shoulder was more open to the camera, or both maybe, something about the pose just strikes me as odd. I think it''s because your shoulder her so straight in line with your head that they compete for attention, and your face should be the focus.</td>', 'This is a very pretty shot of you! Well done. I love your hair. I just have the feeling like... I wish either your head was up a bit or your shoulder was more open to the camera, or both maybe, something about the pose just strikes me as odd. I think it''s because your shoulder her so straight in line with your head that they compete for attention, and your face should be the focus.', '2007-12-05 03:48:16.000000', NULL, 1),
(4290251, 618909, 47316, '<td valign="top">Cool location! I love the bamboos crossing behind you. haha... I had to google Jean Reno, but I recognized him. You do look alike!</td>', 'Cool location! I love the bamboos crossing behind you. haha... I had to google Jean Reno, but I recognized him. You do look alike!', '2007-12-05 03:49:54.000000', NULL, 1),
(4290253, 619450, 44878, '<td valign="top">This is a Nice crisp image, Too much processing of the eyes spoil it a Little fr me and you could have noticed that twig.<br/>I hope you do well young Man !</td>', 'This is a Nice crisp image, Too much processing of the eyes spoil it a Little fr me and you could have noticed that twig.I hope you do well young Man !', '2007-12-05 03:50:44.000000', NULL, 1),
