INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4300750, 619166, 76217, '<td valign="top">I''m guessing you were shooting for "gritty"? You accomplished it.</td>', 'I''m guessing you were shooting for "gritty"? You accomplished it.', '2007-12-08 01:03:05.000000', NULL, 1),
(4300767, 619633, 60862, '<td valign="top">Tease! ;)</td>', 'Tease! ;)', '2007-12-08 01:14:28.000000', NULL, 1),
(4300769, 619674, 60862, '<td valign="top">Happy birthday! :)  I like the idea a lot.  I think I would''ve liked it better if the reflection had been sharp and the real you blurred, instead of the reverse.</td>', 'Happy birthday! :)  I like the idea a lot.  I think I would''ve liked it better if the reflection had been sharp and the real you blurred, instead of the reverse.', '2007-12-08 01:16:37.000000', NULL, 1),
(4300771, 619621, 60862, '<td valign="top">Hilarious! :)  Great angle and I like the tilt.</td>', 'Hilarious! :)  Great angle and I like the tilt.', '2007-12-08 01:17:04.000000', NULL, 1),
(4300772, 619483, 60862, '<td valign="top">Nice idea, but it''s too blurry to hold my interest.</td>', 'Nice idea, but it''s too blurry to hold my interest.', '2007-12-08 01:18:20.000000', NULL, 1),
(4300776, 618028, 60862, '<td valign="top">Intriguing, but ultimately too dark to hold my interest very long.</td>', 'Intriguing, but ultimately too dark to hold my interest very long.', '2007-12-08 01:20:02.000000', NULL, 1),
(4300777, 618342, 60862, '<td valign="top">Interesting processing.  I like it.</td>', 'Interesting processing.  I like it.', '2007-12-08 01:20:48.000000', NULL, 1),
